import {Matrix4,Vector2,Vector4,WebGLRenderTarget,HalfFloatType,ShaderMaterial} from 'three';
import {ProgressivePathState,bindTransport,configurePathLens} from './path-tracing.js';
import {GeometryGIWorld} from './geometry-gi.js';
import {HierarchicalDepthPass} from './hierarchical-depth-gl.js';
import {Pass,FullScreenQuad} from 'three/addons/postprocessing/Pass.js';
import {screenEffectsGLSL,ScreenFrameState} from './screen-effects.js';
const vertexShader='varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}';
const header='uniform sampler2D hbScreenSource,hbScreenDepth,hbScreenHistory,hbSurfaceNormal,hbSurfaceAlbedo,hbObjectMotion,hbDepthHierarchy,hbGeometryScene;uniform mat4 hbInverseVP,hbCurrentVP,hbPreviousVP;uniform vec4 hbTemporal,hbMotion,hbReflection,hbIndirect,hbCoordinates,hbJitter,hbEye,hbForward,hbCamera,hbHierarchy,hbGeometry,hbGeometryInfo,hbGeometryLimits,hbAmbientAO,hbPath,hbPathQuality,hbPathEnvironment,hbPathLens,hbTransport;uniform sampler2D hbSurfaceAmbient;uniform vec2 hbScreenSize;';
const linear='float hbLinearDepth(float d){return hbCamera.z>.5?mix(hbCamera.x,hbCamera.y,d):hbCamera.x*hbCamera.y/max(.000001,hbCamera.y-d*(hbCamera.y-hbCamera.x));}';
export class ScreenEffectsPass extends Pass{
 constructor(){super();this.state=new ScreenFrameState();this.images=[0,1].map(()=>new WebGLRenderTarget(1,1,{type:HalfFloatType,depthBuffer:false}));this.index=0;this.pathState=new ProgressivePathState();const uniforms=Object.fromEntries(['Source','Depth','History','SurfaceNormal','SurfaceAlbedo','ObjectMotion','DepthHierarchy','GeometryScene','SurfaceAmbient'].map(k=>[(k.startsWith('Surface')||k==='ObjectMotion'||k==='DepthHierarchy'||k==='GeometryScene')?'hb'+k:'hbScreen'+k,{value:null}]));for(const key of ['Temporal','Motion','Reflection','Indirect','Coordinates','Jitter','Eye','Forward','Camera','Hierarchy','Geometry','GeometryInfo','GeometryLimits','AmbientAO','Path','PathQuality','PathEnvironment','PathLens','Transport'])uniforms['hb'+key]={value:new Vector4()};for(const key of ['InverseVP','CurrentVP','PreviousVP'])uniforms['hb'+key]={value:new Matrix4()};uniforms.hbScreenSize={value:new Vector2()};this.material=new ShaderMaterial({uniforms,vertexShader,fragmentShader:'varying vec2 vUv;'+header+linear+screenEffectsGLSL+'void main(){gl_FragColor=hbScreenResolve(vUv);}',depthTest:false,depthWrite:false,toneMapped:false});this.copy=new ShaderMaterial({uniforms:{hbResolved:{value:null},hbRaw:{value:null},hbPathAlpha:{value:0}},vertexShader,fragmentShader:'uniform sampler2D hbResolved,hbRaw;uniform float hbPathAlpha;varying vec2 vUv;void main(){gl_FragColor=vec4(texture2D(hbResolved,vUv).rgb,mix(texture2D(hbRaw,vUv).a,1.0,hbPathAlpha));}',depthTest:false,depthWrite:false,toneMapped:false});this.quad=new FullScreenQuad(this.material);}
 prepare(frame,camera,scene,p){const u=this.material.uniforms;for(const [key,value]of Object.entries(frame.packed)){const name='hb'+key[0].toUpperCase()+key.slice(1);if(u[name])u[name].value.fromArray(value);}if(frame.packed.path[0]===0)this.pathState.reset();configurePathLens(frame.packed,camera,p);if(frame.packed.geometry[0]>0||frame.packed.path[0]>0){this.geometry??=new GeometryGIWorld();const p=bindTransport(frame.packed,this.geometry,scene);if(frame.packed.path[0]>0)this.pathState.prepare(frame.packed,this.geometry,frame.reset);for(const key of ['path','pathQuality','pathLens','transport'])u['hb'+key[0].toUpperCase()+key.slice(1)].value.fromArray(frame.packed[key]);this.frame=frame;u.hbGeometryScene.value=this.geometry.texture;u.hbGeometryInfo.value.set(p.width,p.height,p.nodeCount,p.triangleOffset);u.hbGeometryLimits.value.z=p.lightsOffset;u.hbGeometryLimits.value.w=p.lightCount;}else if(this.geometry){this.geometry.dispose();this.geometry=null;u.hbGeometryScene.value=null;this.pathState.reset();}u.hbScreenSize.value.fromArray(frame.packed.size);u.hbCamera.value.set(camera.near,camera.far,camera.isOrthographicCamera?1:0,Math.abs(camera.projectionMatrix.elements[5])*.5);}
 setSize(w,h){for(const image of this.images)image.setSize(w,h);this.state.reset();this.pathState.reset();}
 render(renderer,write,read){read=this.raw||read;const u=this.material.uniforms;u.hbObjectMotion.value=this.motion?.target.texture||null;u.hbScreenSource.value=read.texture;u.hbScreenDepth.value=read.depthTexture;u.hbSurfaceNormal.value=read.textures[1]||null;u.hbSurfaceAlbedo.value=read.textures[2]||null;u.hbSurfaceAmbient.value=read.textures[3]||null;u.hbScreenHistory.value=this.images[this.index].texture;if(u.hbHierarchy.value.w>.5){this.hiz??=new HierarchicalDepthPass();u.hbDepthHierarchy.value=this.hiz.render(renderer,read.depthTexture,read.width,read.height);const l=this.hiz.layout;u.hbHierarchy.value.set(l.width,l.height,l.levels.length,1);}else if(this.hiz){this.hiz.dispose();this.hiz=null;u.hbDepthHierarchy.value=null;}const result=this.images[1-this.index];renderer.setRenderTarget(result);this.quad.material=this.material;this.quad.render(renderer);this.copy.uniforms.hbPathAlpha.value=u.hbPath.value.x;this.copy.uniforms.hbResolved.value=result.texture;this.copy.uniforms.hbRaw.value=read.texture;renderer.setRenderTarget(this.renderToScreen?null:write);this.quad.material=this.copy;this.quad.render(renderer);this.index=1-this.index;if(this.frame?.packed.path[0]>0)this.pathState.commit(this.frame.packed);}
 dispose(){this.geometry?.dispose();this.hiz?.dispose();for(const image of this.images)image.dispose();this.material.dispose();this.copy.dispose();this.quad.dispose();}
}
